scwin.fn_openPopup = function() {
    var options = {
        id: "popup1",
        type: "layer",
        width: "300px",
        height: "300px",
        popupName: "TestPage",
        resizable: false,
        status: false,
        menubar: false,
        scrollbars: false,
        title: true,
        xml: "<FORM>한글입니다</FORM>",
        dataObject: {
            type: "json",
            data: dataList1,
            name: "param1"
        }
    };
    pop = $w.openPopup("", options);
};
scwin.trigger1_onclick = function(e) {
    debugger;
    calendar1.setDisabled(true);
};
scwin.trigger2_onclick = function(e) {
    debugger;
    calendar1.setDisabled(false);
};
scwin.trigger3_onclick = function(e) {
    calendar2.setDisabled(true);
};
scwin.trigger4_onclick = function(e) {
    calendar2.setDisabled(false);
};
scwin.trigger5_onclick = function(e) {
    $w.showModal();
};
scwin.trigger6_onclick = function(e) {
    $w.showModal();
};
scwin.__checkErr = function() {
    return temp = WebSquare.logger.getErrorLog();
}
scwin.getToday = function() {
    var date = new Date();
    dd = date.getDate() > 9 ? date.getDate() : '0' + date.getDate();
    mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    yy = date.getFullYear();
    var today = yy + '-' + mm + '-' + dd;
    return today;
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('inputCalendar2_input').value == scwin.getToday();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 상단의 캘린더(달력아이콘) 클릭 후 날짜를 입력한다.
    //1. After running the sample, click the calendar at the top (calendar icon) and enter the date.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar2_calendar_cell_1_6').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_selected')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar2_input').blur()");
    //Verify 1. renderTpe=native 옆에 날짜가 입력된다.
    //1. The date is entered next to renderTpe = native.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 후 '$w.showModal()'버튼을 클릭 후 로그보기를 수행한다.
    //2. After clicking '$ w.showModal ()' button, execute log view.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. Modal처리가 되고 정상적인 로그가 보여진다. (이전에는 로그오류발생)
    //2. Modal processing is performed and a normal log is displayed. (Previously a log error occurred)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('_modal').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErr() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    //Function unitTest
